const menu=[['/app','LayoutDashboard','Dashboard'],['/app/customers','Users','Customers'],['/app/customers/portal-access','UserRoundCheck','Customer Access'],['/app/requests','MessageSquareText','Service Requests'],['/app/jobs','BriefcaseBusiness','Jobs'],['/app/quotes','FileText','Quotes'],['/app/quotes/ai','Sparkles','AI Quote Generator'],['/app/invoices','ReceiptPoundSterling','Invoices'],['/app/inventory','PackageOpen','Stock'],['/app/engineers','HardHat','Engineers'],['/app/schedule','CalendarDays','Schedule'],['/app/reminders','MailClock','Reminders'],['/app/notifications','Bell','Notifications'],['/app/activity','History','Audit Activity'],['/app/reports','ChartNoAxesCombined','Reports'],['/app/assistant','BrainCircuit','AI Assistant'],['/app/team','UserRoundCog','Team'],['/app/settings','Settings','Settings']];
const Icon=({name,size=19})=>{const C=I[name]||I.Circle;return <C size={size}/>};
const Badge=({children,tone='grey'})=><span className={'app-badge '+tone}>{children}</span>;
export const Button=({children,secondary=false,onClick,type='button',disabled=false,className='',...props})=><button type={type} className={`app-button ${secondary?'secondary':''} ${className}`.trim()} onClick={onClick} disabled={disabled} {...props}>{children}</button>;

const scheduleTimes=Array.from({length:17},(_,index)=>{
  const hour=index+6;
  const value=`${String(hour).padStart(2,'0')}:00`;
  const label=new Date(2026,0,1,hour).toLocaleTimeString('en-GB',{hour:'numeric',minute:'2-digit',hour12:true});
  return [value,label];
});
export function ScheduleDateTimeField({name,label,defaultValue='',required=false,defaultTime='09:00'}){
  const initial=String(defaultValue||'').slice(0,16);
  const [date,setDate]=useState(initial.slice(0,10));
  const [time,setTime]=useState(initial.slice(11,16)||defaultTime);
  return <label className="schedule-date-time"><span>{label}</span><div><input type="date" value={date} onChange={event=>setDate(event.target.value)} required={required} aria-label={`${label} date`}/><select value={time} onChange={event=>setTime(event.target.value)} aria-label={`${label} time`}><option value="" disabled>Select time</option>{scheduleTimes.map(([value,text])=><option value={value} key={value}>{text}</option>)}</select></div><input type="hidden" name={name} value={date&&time?`${date}T${time}`:''}/></label>;
}

export function AppShell({children,title,subtitle,action}){
  const [mobile,setMobile]=useState(false),[session,setSession]=useState(null),[company,setCompany]=useState(null),[accountOpen,setAccountOpen]=useState(false),[unread,setUnread]=useState(0);const navigate=useNavigate();
  useEffect(()=>{let active=true;Promise.all([api.me(),api.company.get().catch(()=>null),api.notifications.list().catch(()=>[])]).then(([me,workspace,notifications])=>{if(active){setSession(me.user);setCompany(workspace);setUnread(notifications.filter(item=>!item.isRead).length)}}).catch(()=>{});return()=>{active=false}},[]);
  useEffect(()=>{
    const improveDateTimeInputs=root=>{
      const inputs=[...(root.matches?.('input[type="datetime-local"]')?[root]:[]),...(root.querySelectorAll?.('input[type="datetime-local"]')||[])];
      inputs.forEach(input=>{
        if(input.dataset.roundedSchedule)return;
        input.dataset.roundedSchedule='true';
        const raw=input.value||input.defaultValue||'';
        const wrapper=document.createElement('div');
        const dateInput=document.createElement('input');
        const timeSelect=document.createElement('select');
        wrapper.className='rounded-date-time';
        dateInput.type='date';
        dateInput.value=raw.slice(0,10);
        dateInput.required=input.required;
        dateInput.setAttribute('aria-label',`${input.name||'Schedule'} date`);
        const existingHour=raw.slice(11,13);
        const fallback=input.name?.toLowerCase().includes('end')?'11:00':'09:00';
        const selectedTime=existingHour?`${existingHour}:00`:fallback;
        scheduleTimes.forEach(([value,text])=>{const option=document.createElement('option');option.value=value;option.textContent=text;timeSelect.append(option)});
        timeSelect.value=selectedTime;
        timeSelect.setAttribute('aria-label',`${input.name||'Schedule'} time`);
        const sync=()=>{input.value=dateInput.value&&timeSelect.value?`${dateInput.value}T${timeSelect.value}`:''};
        dateInput.addEventListener('change',sync);
        timeSelect.addEventListener('change',sync);
        input.required=false;
        input.type='hidden';
        wrapper.append(dateInput,timeSelect);
        input.before(wrapper);
        sync();
      });
    };
    improveDateTimeInputs(document);
    const observer=new MutationObserver(records=>records.forEach(record=>record.addedNodes.forEach(node=>{
      if(node.nodeType===Node.ELEMENT_NODE){
        improveDateTimeInputs(node);
      }
    })));
    observer.observe(document.body,{childList:true,subtree:true});
    return()=>observer.disconnect();
  },[]);
  const fullName=session?.fullName||session?.email||'Account user',initials=fullName.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase(),role=session?.role?session.role[0].toUpperCase()+session.role.slice(1):'Secure account';
  const logout=async()=>{await logoutFirebase();navigate('/login',{replace:true})};
  const search=e=>{e.preventDefault();const query=new FormData(e.currentTarget).get('query')?.trim();if(query)navigate(`/app/jobs?search=${encodeURIComponent(query)}`)};
  return <div className="app-shell"><aside className={mobile?'app-side open':'app-side'}><Link className="app-logo" to="/"><img src="/assets/logo.png" alt="SecureVision AI"/></Link><nav>{menu.map(([to,icon,label])=><NavLink key={to} end={to==='/app'} to={to} onClick={()=>setMobile(false)}><Icon name={icon}/><span>{label}</span>{label==='AI Assistant'&&<em>AI</em>}</NavLink>)}</nav><div className="app-help"><I.ShieldCheck/><b>{company?.name||'Secure workspace'}</b><small>Authenticated company access</small><Link to="/app/settings">Workspace settings</Link></div><div className="app-user"><div className="avatar">{initials}</div><span><b>{fullName}</b><small>{role}</small></span><button onClick={logout} aria-label="Sign out" title="Sign out"><I.LogOut/></button></div></aside><div className="app-main"><header className="app-top"><button className="app-menu" onClick={()=>setMobile(!mobile)} aria-label="Open app menu"><I.Menu/></button><form className="app-search" onSubmit={search}><I.Search/><input name="query" aria-label="Search jobs" placeholder="Search jobs by reference, customer or title..."/><kbd>Enter</kbd></form><Link className="round" to="/app/assistant" aria-label="Open AI Assistant" title="AI Assistant"><I.BrainCircuit/></Link><div className="account-menu"><button className="top-avatar" onClick={()=>setAccountOpen(value=>!value)} aria-expanded={accountOpen} aria-label="Open account menu">{initials}</button>{accountOpen&&<div><span><b>{fullName}</b><small>{session?.email}</small></span><Link to="/app/settings" onClick={()=>setAccountOpen(false)}><I.Settings/>Settings</Link><button onClick={logout}><I.LogOut/>Sign out</button></div>}</div></header><main className="app-content"><div className="app-heading"><div><h1>{title}</h1><p>{subtitle}</p></div>{action}</div>{children}</main></div></div>
}

const metrics=[['BriefcaseBusiness','Total Jobs','128','+18%','red'],['Clock3','Pending Jobs','24','+12%','amber'],['CircleCheckBig','Completed Jobs','104','+24%','green'],['Banknote','Total Revenue','£28,540','+15%','blue']];
const upcoming=[['SV-1042','Site Survey - Office Complex','Oakfield Business Park','Today, 09:00','James Wilson','Survey'],['IN-1041','CCTV Installation - Warehouse','Vector Logistics','Today, 11:30','Liam Carter','Installation'],['MA-1040','Alarm Maintenance - Retail','Westfield Stores','Tomorrow, 08:30','Sophie Brown','Maintenance'],['AC-1039','Access Control Setup','Vantage House','Tomorrow, 13:00','Daniel Evans','Installation']];
export function AdminDashboard(){return <AppShell title="Dashboard" subtitle="Welcome back. Here’s what’s happening today." action={<Button onClick={()=>alert('New job workflow ready')}><I.Plus/>Create Job</Button>}><div className="metric-grid">{metrics.map(([ic,l,n,c,t])=><article className="metric-card" key={l}><div className={'metric-icon '+t}><Icon name={ic}/></div><span><small>{l}</small><strong>{n}</strong><em>{c} <i>from last month</i></em></span></article>)}</div><div className="dash-layout"><Panel title="Jobs Overview" extra={<select><option>This month</option><option>Last month</option></select>}><div className="big-chart"><div className="chart-y"><span>100</span><span>75</span><span>50</span><span>25</span><span>0</span></div><svg viewBox="0 0 760 230" preserveAspectRatio="none"><defs><linearGradient id="area"><stop stopColor="#ef233c" stopOpacity=".38"/><stop offset="1" stopColor="#ef233c" stopOpacity="0"/></linearGradient></defs><path d="M0,190 L70,145 L140,115 L210,150 L280,90 L350,70 L420,120 L490,80 L560,35 L630,85 L700,55 L760,10 L760,230 L0,230Z" fill="url(#area)"/><polyline points="0,190 70,145 140,115 210,150 280,90 350,70 420,120 490,80 560,35 630,85 700,55 760,10" fill="none" stroke="#ef233c" strokeWidth="4"/></svg><div className="chart-x">{['Jan','Feb','Mar','Apr','May','Jun','Jul'].map(x=><span key={x}>{x}</span>)}</div></div></Panel><Panel title="Upcoming Jobs" extra={<Link to="/app/jobs">View all</Link>}><div className="upcoming">{upcoming.map(j=><div key={j[0]}><div className="datebox"><b>{j[3].split(', ')[1]}</b><small>{j[3].split(', ')[0]}</small></div><span><b>{j[1]}</b><small>{j[2]} · {j[4]}</small></span><Badge tone={j[5]==='Survey'?'blue':'amber'}>{j[5]}</Badge></div>)}</div></Panel></div><div className="bottom-grid"><Panel title="AI Insights" icon="BrainCircuit"><div className="insight"><I.Sparkles/><div><b>Demand forecast</b><p>CCTV installation demand is forecast to rise 18% over the next 30 days.</p><Link to="/app/assistant">View insight <I.ArrowRight/></Link></div></div></Panel><Panel title="Invoices Overview"><div className="invoice-total"><span><small>Paid this month</small><b>£18,250</b></span><div><b>£4,820</b><small>Outstanding</small></div></div><div className="progress"><i style={{width:'79%'}}/></div></Panel><Panel title="Engineer Status"><div className="engineer-ring"><div><strong>12</strong><small>Engineers</small></div><ul><li><i className="green"/>On Job <b>8</b></li><li><i className="blue"/>Available <b>3</b></li><li><i className="grey"/>Off Duty <b>1</b></li></ul></div></Panel></div></AppShell>}
function Panel({title,extra,children,icon}){return <section className="app-panel"><header><h2>{icon&&<Icon name={icon}/>} {title}</h2>{extra}</header>{children}</section>}

const customers=[];
export function Customers(){
  const [q,setQ]=useState(''),[rows,setRows]=useState(customers),[open,setOpen]=useState(false),[editing,setEditing]=useState(null),[notice,setNotice]=useState('Loading customer data...');
  const load=async()=>{try{const data=await api.customers.list();setRows(data.map(c=>[c.companyName,c.contactName,c.email,String(c.sites||0),new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',maximumFractionDigits:0}).format(c.totalValue||0),c.status,c.id]));setNotice('Connected to SecureVision API')}catch{setNotice('API offline — showing local demonstration data')}};
  useEffect(()=>{load()},[]);
  const filtered=useMemo(()=>rows.filter(x=>x.join(' ').toLowerCase().includes(q.toLowerCase())),[q,rows]);
  const create=async data=>{try{await api.customers.create(data);setNotice('Customer saved successfully');setOpen(false);await load()}catch(error){setNotice(error.message)}};
  const edit=async id=>{setNotice('Loading customer details…');try{setEditing(await api.customers.get(id));setNotice('Customer loaded for editing.')}catch(error){setNotice(error.message)}};
  const update=async data=>{try{await api.customers.update(editing.id,data);setEditing(null);setNotice('Customer updated successfully');await load()}catch(error){setNotice(error.message)}};
  return <AppShell title="Customers" subtitle="Manage customer accounts, contacts, sites and service history." action={<Button onClick={()=>setOpen(true)}><I.UserPlus/>Add Customer</Button>}><div className="connection-note"><I.Database/>{notice}</div><QuickStats items={[[rows.length,'Total customers'],[rows.filter(x=>x[5]==='Active').length,'Active contracts'],[rows.reduce((n,x)=>n+Number(x[3]),0),'Customer sites'],['£72.2k','Customer value']]}/><TablePanel search={q} setSearch={setQ} placeholder="Search customers..."><table><thead><tr><th>Customer</th><th>Primary Contact</th><th>Sites</th><th>Total Value</th><th>Status</th><th>Actions</th></tr></thead><tbody>{filtered.map(c=><tr key={c[6]||c[0]}><td><EntityAvatar name={c[0]}/></td><td><b>{c[1]}</b><small>{c[2]}</small></td><td>{c[3]}</td><td><b>{c[4]}</b></td><td><Badge tone={c[5]==='Active'?'green':c[5]==='Lead'?'blue':'grey'}>{c[5]}</Badge></td><td><div className="table-actions">{c[6]&&<><Button secondary onClick={()=>edit(c[6])}><I.Pencil size={15}/>Edit</Button><Link className="icon-button" to={`/app/customers/${c[6]}`} aria-label={`View ${c[0]}`}><I.ArrowRight/></Link></>}</div></td></tr>)}</tbody></table></TablePanel>{open&&<CustomerModal onClose={()=>setOpen(false)} onSave={create}/>} {editing&&<CustomerModal customer={editing} onClose={()=>setEditing(null)} onSave={update}/>}</AppShell>;
}

const jobs=[];
export function Jobs(){const location=useLocation(),initialSearch=new URLSearchParams(location.search).get('search')||'';const [view,setView]=useState('list'),[q,setQ]=useState(initialSearch),[rows,setRows]=useState(jobs);const [customersForForm,setCustomersForForm]=useState([]);const [open,setOpen]=useState(false);const [notice,setNotice]=useState('Loading job data...');useEffect(()=>{Promise.all([api.jobs.list(),api.customers.list()]).then(([data,customerData])=>{setRows(data.map(j=>[j.reference,j.title,j.customerName,j.engineerName,new Date(j.dueDate).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}),j.status,j.priority,j.id]));setCustomersForForm(customerData);setNotice('Connected to SecureVision API')}).catch(()=>setNotice('API offline — showing local demonstration data'))},[]);useEffect(()=>{setQ(new URLSearchParams(location.search).get('search')||'')},[location.search]);const visibleRows=useMemo(()=>rows.filter(row=>row.join(' ').toLowerCase().includes(q.toLowerCase())),[rows,q]);const create=async data=>{try{const saved=await api.jobs.create(data);setRows(r=>[[saved.reference,saved.title,saved.customerName,saved.engineerName,new Date(saved.dueDate).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}),saved.status,saved.priority,saved.id],...r]);setOpen(false);setNotice('Job created successfully')}catch(error){setNotice(error.message)}};return <AppShell title="Jobs" subtitle="Create, assign and track every job from enquiry to completion." action={<Button onClick={()=>setOpen(true)}><I.Plus/>Create Job</Button>}><div className="connection-note"><I.Database/>{notice}</div><div className="toolbar"><div className="segmented"><button className={view==='list'?'active':''} onClick={()=>setView('list')}><I.List/>List</button><button className={view==='board'?'active':''} onClick={()=>setView('board')}><I.Columns3/>Board</button></div></div>{view==='list'?<TablePanel search={q} setSearch={setQ} placeholder="Search jobs..."><table><thead><tr><th>Job</th><th>Customer</th><th>Engineer</th><th>Due Date</th><th>Priority</th><th>Status</th></tr></thead><tbody>{visibleRows.map(j=><tr key={j[7]||j[0]}><td>{j[7]?<Link className="job-link" to={`/app/jobs/${j[7]}`}><b>{j[0]}</b><small>{j[1]}</small></Link>:<><b>{j[0]}</b><small>{j[1]}</small></>}</td><td>{j[2]}</td><td>{j[3]}</td><td>{j[4]}</td><td><Badge tone={j[6]==='Urgent'?'red':j[6]==='High'?'amber':'grey'}>{j[6]}</Badge></td><td><Badge tone={j[5]==='Completed'?'green':j[5]==='In Progress'?'blue':'amber'}>{j[5]}</Badge></td></tr>)}</tbody></table></TablePanel>:<Kanban rows={visibleRows}/>} {open&&<JobModal customers={customersForForm} onClose={()=>setOpen(false)} onCreate={create}/>}</AppShell>}
function Kanban({rows=jobs}){return <div className="kanban">{['Pending','Scheduled','In Progress','Completed'].map(s=><section key={s}><header><b>{s}</b><span>{rows.filter(j=>j[5]===s).length}</span></header>{rows.filter(j=>j[5]===s).map(j=><article key={j[7]||j[0]}><Badge tone={j[6]==='Urgent'?'red':'grey'}>{j[6]}</Badge><h3>{j[1]}</h3><p>{j[2]}</p><footer><span>{j[0]}</span><span><I.Calendar/> {j[4].slice(0,6)}</span></footer></article>)}</section>)}</div>}

